// Insert inserts the record into the database
func (t *ItemPrice) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ItemPriceTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Item_no,
		t.Price_group_code,
		t.Unit_of_measure_code,
		t.Currency_code,
		types.KeyDate(t.Starting_date),
		t.Unit_price,
		t.Price_includes_tax,
		t.Allow_quantity_disc,
		t.Allow_cust_item_disc,
		t.Allow_invoice_disc,
		t.Tax_bus_posting_gr_price,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (item_no, price_group_code, unit_of_measure_code, currency_code, starting_date, unit_price, price_includes_tax, allow_quantity_disc, allow_cust_item_disc, allow_invoice_disc, tax_bus_posting_gr_price) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (item_no, price_group_code, unit_of_measure_code, currency_code, starting_date) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Item_Price: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(ItemPriceTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *ItemPrice) InsertAll(records []*ItemPrice, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Item_no,
			r.Price_group_code,
			r.Unit_of_measure_code,
			r.Currency_code,
			types.KeyDate(r.Starting_date),
			r.Unit_price,
			r.Price_includes_tax,
			r.Allow_quantity_disc,
			r.Allow_cust_item_disc,
			r.Allow_invoice_disc,
			r.Tax_bus_posting_gr_price,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ItemPriceTableName)
	columns := []string{"item_no", "price_group_code", "unit_of_measure_code", "currency_code", "starting_date", "unit_price", "price_includes_tax", "allow_quantity_disc", "allow_cust_item_disc", "allow_invoice_disc", "tax_bus_posting_gr_price"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *ItemPrice) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("item_no") {
			keyChanged = true
		}
		if t.hasFieldChanged("price_group_code") {
			keyChanged = true
		}
		if t.hasFieldChanged("unit_of_measure_code") {
			keyChanged = true
		}
		if t.hasFieldChanged("currency_code") {
			keyChanged = true
		}
		if t.hasFieldChanged("starting_date") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ItemPriceTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("item_no") {
			setClauses = append(setClauses, "item_no = ?")
			values = append(values, t.Item_no)
		}
		if t.hasFieldChanged("price_group_code") {
			setClauses = append(setClauses, "price_group_code = ?")
			values = append(values, t.Price_group_code)
		}
		if t.hasFieldChanged("unit_of_measure_code") {
			setClauses = append(setClauses, "unit_of_measure_code = ?")
			values = append(values, t.Unit_of_measure_code)
		}
		if t.hasFieldChanged("currency_code") {
			setClauses = append(setClauses, "currency_code = ?")
			values = append(values, t.Currency_code)
		}
		if t.hasFieldChanged("starting_date") {
			setClauses = append(setClauses, "starting_date = ?")
			values = append(values, types.KeyDate(t.Starting_date))
		}
		if t.hasFieldChanged("unit_price") {
			setClauses = append(setClauses, "unit_price = ?")
			values = append(values, t.Unit_price)
		}
		if t.hasFieldChanged("price_includes_tax") {
			setClauses = append(setClauses, "price_includes_tax = ?")
			values = append(values, t.Price_includes_tax)
		}
		if t.hasFieldChanged("allow_quantity_disc") {
			setClauses = append(setClauses, "allow_quantity_disc = ?")
			values = append(values, t.Allow_quantity_disc)
		}
		if t.hasFieldChanged("allow_cust_item_disc") {
			setClauses = append(setClauses, "allow_cust_item_disc = ?")
			values = append(values, t.Allow_cust_item_disc)
		}
		if t.hasFieldChanged("allow_invoice_disc") {
			setClauses = append(setClauses, "allow_invoice_disc = ?")
			values = append(values, t.Allow_invoice_disc)
		}
		if t.hasFieldChanged("tax_bus_posting_gr_price") {
			setClauses = append(setClauses, "tax_bus_posting_gr_price = ?")
			values = append(values, t.Tax_bus_posting_gr_price)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "unit_price = ?")
		values = append(values, t.Unit_price)
		setClauses = append(setClauses, "price_includes_tax = ?")
		values = append(values, t.Price_includes_tax)
		setClauses = append(setClauses, "allow_quantity_disc = ?")
		values = append(values, t.Allow_quantity_disc)
		setClauses = append(setClauses, "allow_cust_item_disc = ?")
		values = append(values, t.Allow_cust_item_disc)
		setClauses = append(setClauses, "allow_invoice_disc = ?")
		values = append(values, t.Allow_invoice_disc)
		setClauses = append(setClauses, "tax_bus_posting_gr_price = ?")
		values = append(values, t.Tax_bus_posting_gr_price)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["item_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Item_no)
	}
	if old, ok := t.oldValues["price_group_code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Price_group_code)
	}
	if old, ok := t.oldValues["unit_of_measure_code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Unit_of_measure_code)
	}
	if old, ok := t.oldValues["currency_code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Currency_code)
	}
	if old, ok := t.oldValues["starting_date"]; ok {
		values = append(values, types.KeyDate(old))
	} else {
		values = append(values, types.KeyDate(t.Starting_date))
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND item_no = ? AND price_group_code = ? AND unit_of_measure_code = ? AND currency_code = ? AND starting_date = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Item_Price: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *ItemPrice) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "item_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Item_no.Equal(old)
		}
	case "price_group_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Price_group_code.Equal(old)
		}
	case "unit_of_measure_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Unit_of_measure_code.Equal(old)
		}
	case "currency_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Currency_code.Equal(old)
		}
	case "starting_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Starting_date.Equal(old)
		}
	case "unit_price":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Unit_price.Equal(old)
		}
	case "price_includes_tax":
		if old, ok := oldValue.(bool); ok {
			return t.Price_includes_tax != old
		}
		return true // Type mismatch, assume changed
	case "allow_quantity_disc":
		if old, ok := oldValue.(bool); ok {
			return t.Allow_quantity_disc != old
		}
		return true // Type mismatch, assume changed
	case "allow_cust_item_disc":
		if old, ok := oldValue.(bool); ok {
			return t.Allow_cust_item_disc != old
		}
		return true // Type mismatch, assume changed
	case "allow_invoice_disc":
		if old, ok := oldValue.(bool); ok {
			return t.Allow_invoice_disc != old
		}
		return true // Type mismatch, assume changed
	case "tax_bus_posting_gr_price":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Tax_bus_posting_gr_price.Equal(old)
		}
	}

	return false
}

