func (t *ItemPrice) SetFilter(fieldName, filterExpr string) {
	if t.filters == nil {
		t.filters = make(map[string]*itemPriceFilterCondition)
	}
	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetFilter on unknown field %q of Item_Price\n", fieldName)
		t.filters[fieldName] = &itemPriceFilterCondition{invalidField: true}
		return
	}
	t.filters[column] = &itemPriceFilterCondition{
		fieldName:    column,
		filterExpr:   filterExpr,
		isExpression: true,
	}
}

