// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *ItemPrice) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var item_noNull sql.NullString
		var price_group_codeNull sql.NullString
		var unit_of_measure_codeNull sql.NullString
		var currency_codeNull sql.NullString
		var starting_dateNull sql.NullString
		var unit_priceNull sql.NullString
		var price_includes_taxBool sql.NullBool
		var allow_quantity_discBool sql.NullBool
		var allow_cust_item_discBool sql.NullBool
		var allow_invoice_discBool sql.NullBool
		var tax_bus_posting_gr_priceNull sql.NullString

		err := t.currentRows.Scan(
			&item_noNull,
			&price_group_codeNull,
			&unit_of_measure_codeNull,
			&currency_codeNull,
			&starting_dateNull,
			&unit_priceNull,
			&price_includes_taxBool,
			&allow_quantity_discBool,
			&allow_cust_item_discBool,
			&allow_invoice_discBool,
			&tax_bus_posting_gr_priceNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Item_Price record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.Item_no = types.NewCode(item_noNull.String)
		t.Price_group_code = types.NewCode(price_group_codeNull.String)
		t.Unit_of_measure_code = types.NewCode(unit_of_measure_codeNull.String)
		t.Currency_code = types.NewCode(currency_codeNull.String)
		t.Starting_date, _ = types.NewDateFromString(starting_dateNull.String)
		t.Unit_price, _ = types.NewDecimalFromString(unit_priceNull.String)
		t.Price_includes_tax = price_includes_taxBool.Bool
		t.Allow_quantity_disc = allow_quantity_discBool.Bool
		t.Allow_cust_item_disc = allow_cust_item_discBool.Bool
		t.Allow_invoice_disc = allow_invoice_discBool.Bool
		t.Tax_bus_posting_gr_price = types.NewCode(tax_bus_posting_gr_priceNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No record set (after Get, Find, FindFirst, FindLast): the next record in the current key
	// and direction within the filters, one step at a time (classic NEXT after FIND); a step
	// that finds none leaves the record on the last one reached
	if step == 0 {
		return false
	}
	for i := 0; i != step; {
		if step > 0 {
			if !t.findInKey(">", false) {
				return false
			}
			i++
		} else {
			if !t.findInKey("<", true) {
				return false
			}
			i--
		}
	}
	return true
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *ItemPrice) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := fmt.Sprintf("%s$%s", t.company, ItemPriceTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT item_no, price_group_code, unit_of_measure_code, currency_code, starting_date, unit_price, price_includes_tax, allow_quantity_disc, allow_cust_item_disc, allow_invoice_disc, tax_bus_posting_gr_price FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for Item_Price: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &ItemPrice{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var item_noNull sql.NullString
		var price_group_codeNull sql.NullString
		var unit_of_measure_codeNull sql.NullString
		var currency_codeNull sql.NullString
		var starting_dateNull sql.NullString
		var unit_priceNull sql.NullString
		var price_includes_taxBool sql.NullBool
		var allow_quantity_discBool sql.NullBool
		var allow_cust_item_discBool sql.NullBool
		var allow_invoice_discBool sql.NullBool
		var tax_bus_posting_gr_priceNull sql.NullString

		err := rows.Scan(
			&item_noNull,
			&price_group_codeNull,
			&unit_of_measure_codeNull,
			&currency_codeNull,
			&starting_dateNull,
			&unit_priceNull,
			&price_includes_taxBool,
			&allow_quantity_discBool,
			&allow_cust_item_discBool,
			&allow_invoice_discBool,
			&tax_bus_posting_gr_priceNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Item_Price record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.Item_no = types.NewCode(item_noNull.String)
		record.Price_group_code = types.NewCode(price_group_codeNull.String)
		record.Unit_of_measure_code = types.NewCode(unit_of_measure_codeNull.String)
		record.Currency_code = types.NewCode(currency_codeNull.String)
		record.Starting_date, _ = types.NewDateFromString(starting_dateNull.String)
		record.Unit_price, _ = types.NewDecimalFromString(unit_priceNull.String)
		record.Price_includes_tax = price_includes_taxBool.Bool
		record.Allow_quantity_disc = allow_quantity_discBool.Bool
		record.Allow_cust_item_disc = allow_cust_item_discBool.Bool
		record.Allow_invoice_disc = allow_invoice_discBool.Bool
		record.Tax_bus_posting_gr_price = types.NewCode(tax_bus_posting_gr_priceNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate Item_Price records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

